import json, urllib.request
url='https://quay.io/api/v1/repository/biocontainers/pybigwig/tag/?limit=100'
try:
    with urllib.request.urlopen(url, timeout=30) as f:
        d=json.load(f)
    for t in d.get('tags',[]):
        n=t.get('name','')
        if 'py3' in n or n.startswith('0.3'):
            print(n)
except Exception as e:
    print(type(e).__name__, e)
PY"

